INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('El MRR – Ingresos Pasivos que se Construyen Mes a Mes', 'El 3% MRR se paga mensualmente durante 12 meses sobre las licencias activas de cada cliente que el Hunter trajo. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional. El MRR es el sueño del vendedor: ingresos que llegan sin esfuerzo adicional.', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin esfuerzo adicional.', 1),
('Los Bonos – Gasolina Extra para el Esfuerzo', 'Bonos escalonados: Bono de Inicio S/408 (3 ventas en primer mes), Ejecutivo Ideal S/850 (5 ventas/mes), Top Performer S/1,020 (7 ventas/mes), Bono Trimestral S/3,400 (promedio 10 ventas/mes). Los bonos transforman un buen mes en un mes excepcional y recompensan la consistencia. Son la gasolina que impulsa al Hunter a ir más allá de la meta mínima.', 'Un Hunter tiene un mes con 7 ventas. Base: S/2,958. Comisiones: S/980. Bono: S/1,020. Total: S/4,958. Si mantiene 10 ventas/mes en el trimestre, gana S/3,400 adicionales. La diferencia entre 5 y 7 ventas es S/170 de bono extra; entre 7 y 10, el bono trimestral de S/3,400. El esfuerzo adicional se paga solo.', 2),
('"Venta Grande Vale por Tres" – Apunta a lo Grande', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (ej. una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio. Una venta grande puede catapultar el ingreso del Hunter en un solo mes.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas.', 3),
('El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre. La consistencia es la clave para escalar al nivel Elite.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', 4),
('La Comparación con Números – El Argumento del Ahorro', 'El Hunter debe comparar INVU con las alternativas del mercado peruano con datos concretos. Sumar el costo del PSE externo, el soporte aparte y las horas de configuración que la competencia no incluye. Mostrar que INVU (S/350/mes todo incluido) es más barato que la competencia (S/450/mes con PSE y soporte). La diferencia de S/100 es el 0.2% de la facturación de un restaurante de S/50,000. Los números son el arma más poderosa del Hunter.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene. Esa diferencia de S/100 al mes es el 0.2% de tu facturación."', 5),
('La Objeción "Es Caro" – El Protocolo Gravity en Acción', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity para "es caro" tiene 5 pasos: Validar (entiendo que el precio es importante), Diagnosticar (¿qué te parece caro exactamente?), Reencuadrar (cuando sumas el PSE, el costo real es mayor), Micro-cierre (¿te parece si hacemos el cálculo con tus números?), y Cierre (¿qué día te acomoda para la demo?). Este protocolo convierte la objeción en una oportunidad de cierre.', 'Cliente: "Es caro."  
Hunter:  
"Entiendo que el precio es una consideración importante."  
"¿Qué es lo que te parece caro exactamente, el setup o las licencias mensuales?"  
"Cuando sumas lo que pagas por Nubefact (S/120/mes), soporte (S/80/mes) y sistemas separados, el costo real de la competencia es S/450/mes. INVU es S/350/mes todo incluido."  
"¿Te parece si hacemos el cálculo con tus números actuales?"  
"¿Qué día te acomoda para la demo?"', 6),
('La Objeción "Ya Tengo un POS" – Diagnosticar el Dolor Oculto', 'El cliente que dice "ya tengo un POS" no está cerrado; está diciendo que no ve razón para cambiar. El Hunter debe diagnosticar qué le falta a su sistema actual. Preguntas: "¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real?" Si no tiene esas funcionalidades, INVU es una mejora, no un cambio. El dolor oculto es la llave para abrir la venta.', '"Me alegra que tengas un sistema. ¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. No se trata de cambiar por cambiar. Se trata de tener una operación rentable."', 7),
('La Objeción "Lo Voy a Pensar" – El Costo de la Postergación', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El Hunter debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, y cerrar ofreciendo una demo sin compromiso. El costo de postergar es el argumento que mueve al cliente a actuar.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos."', 8),
('El Setup – Inversión, No Gasto', 'El setup de INVU es un desembolso inicial que muchos clientes ven como un gasto. El Hunter debe reencuadrarlo como una inversión que ahorra meses de operación rota. La competencia no cobra setup porque no hace nada: da el software y el cliente lo configura. INVU cobra setup porque deja el restaurante operando desde el día uno. El setup es inversión, no gasto. Esta reencuadre cambia la percepción del cliente.', '"Entiendo que el setup es un desembolso inicial importante. Ese setup lo pagás una vez y te ahorra meses de operación rota. Además te lo podemos plantear como facturación anual con mejor precio. La competencia no cobra setup porque no hace nada: te dan el software y tú lo configuras. INVU te deja el restaurante operando desde el día uno. El setup es inversión, no gasto."', 9),
('El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al Hunter profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al Hunter con datos reales. Lo que no está en CRM, no existe. Esta es la regla de oro del Hunter.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', 10),
('El Caso del Restaurante con Facturación Externa y Múltiples Sedes – El Cliente Ideal', 'Un cliente con 3 sedes que paga Nubefact aparte y no tiene control centralizado es el cliente ideal para INVU. El Hunter debe mostrar que el costo actual (S/1,110/mes) es solo un poco menor que INVU (S/1,862/mes), pero que INVU incluye centralización, FE nativa, KDS y Loyalty. El ahorro en mermas (2% = S/2,400/mes) y comisiones de delivery cubren la diferencia. Este caso es el ejemplo perfecto para demostrar el ROI de INVU.', '"Entiendo que el costo de INVU es mayor que lo que pagas hoy. Hoy pagas S/1,110 mensuales: S/750 por los 3 POS y S/360 por Nubefact. Con INVU, el costo mensual es S/1,862, que incluye centralización, FE nativa, KDS y Loyalty. La diferencia es S/752, que es el 0.6% de tu facturación mensual. Pero lo que no estás viendo es lo que te cuesta no tener centralización: precios desactualizados, inventario que no cuadra, mermas sin control. Si reducimos tus mermas en un 2%, son S/2,400 mensuales de ahorro. La inversión se paga sola."', 11),
('Los Errores que Matan la Venta – Lo que el Hunter Debe Evitar', 'Hay 6 errores comunes que el Hunter debe evitar: Hablar de precio antes de diagnosticar; hacer una demo genérica sin enfocarse en el dolor; no sumar los costos ocultos de la competencia; no comparar con la competencia local; no cerrar con una pregunta de avance; hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza". Evitarlos es el primer paso para ser un Hunter Elite.', 'Un cliente pregunta: "¿Cuánto cuesta?"  
El Hunter novato responde: "S/350/mes." El cliente dice: "Es caro." Se va.  
El Hunter experto responde: "El costo depende de tus necesidades. Permíteme hacerte algunas preguntas para entender tu operación y darte una cotización precisa. ¿Cuántas sedes tienes? ¿Qué sistema usas hoy?" El cliente se queda, responde, y el Hunter construye valor antes de dar el precio.', 12),
('Los Niveles de Dominio – De Básico a Gravedad Cero', 'El Hunter pasa por 4 niveles: Básico (explica el producto sin conectar beneficios), Medio (conecta beneficios y diagnostica), Alto (justifica el precio y maneja objeciones con autoridad), y Gravedad Cero (controla la conversación y cierra con autoridad, sin descuentos). El objetivo es llegar a Gravedad Cero: ser un asesor estratégico del restaurantero, no un vendedor más. Cada nivel es un escalón que el Hunter debe subir con disciplina y práctica.', 'Básico: "INVU tiene facturación electrónica nativa."  
Medio: "INVU incluye FE nativa, así que te ahorras S/120/mes en Nubefact."  
Alto: "Cuando sumas el PSE, soporte y sistemas separados, la competencia te cuesta S/450/mes. INVU es S/350/mes todo incluido. Y el onboarding consultivo te da visibilidad de márgenes que nunca tuviste."  
Gravedad Cero: El cliente dice: "¿Qué necesito firmar?" El Hunter ya no vende; el cliente compra porque confía en él.', 13),
('El Potencial de Ingresos del Hunter – Sin Techos, Sin Límites', 'El Hunter tiene un potencial de ingresos ilimitado. Desde S/35,496 anuales (3 ventas/mes) hasta más de S/100,000 anuales (Hunter Elite con cuentas grandes). El ingreso está directamente ligado al esfuerzo y la consistencia. No hay techos artificiales; el cielo es el límite. Cada venta adicional es puro ingreso incremental. El Hunter que entiende esto, se motiva a dar siempre un paso más.', '3 ventas/mes: S/35,496 anuales.  
5 ventas/mes: S/51,576 a S/60,576 anuales.  
7 ventas/mes: S/65,544 a S/77,496 anuales.  
10 ventas/mes: S/84,708 a S/108,612 anuales.  
Hunter Elite con cuentas grandes: S/100,000+ anuales.  
El potencial es ilimitado. El Hunter que construye una cartera de clientes y mantiene un ritmo constante, puede generar ingresos equivalentes a un salario ejecutivo.', 14),
('El Valor del Onboarding Consultivo para el Hunter', 'El onboarding consultivo de INVU es un diferenciador clave que el Hunter debe comunicar. INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación rentable: menú con recetas costeadas, materia prima, proveedores, márgenes reales por plato. Muchos dueños operan a ciegas: no saben cuánto ganan por plato, no controlan mermas. El onboarding consultivo transforma al vendedor en un asesor de confianza y es un argumento de cierre poderoso.', '"No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca ha visto el margen real de sus platos, percibe a INVU como un socio, no como un proveedor.', 15)) AS t(concepto, enseñanza, ejemplo, orden);